import React from "react";

// Horizontal release timeline (replaces the old range slider). Clicking a dot re-scopes the whole
// page to that release. `releases` are display dates (oldest first); `marks` puts a small label
// over a dot (the first LiveBench 2.0 release carries "2.0").
export default function ReleaseTimeline({ releases, value, onChange, marks = {}, tips = {} }) {
  const idx = Math.max(0, releases.indexOf(value));
  const last = releases.length - 1;
  const pct = (i) => (last === 0 ? 0 : (i / last) * 100);
  return (
    <div className="lb-tl">
      <div className="lb-tl-head">
        <span className="lab">Release</span>
        <span className="date">{value}</span>
      </div>
      <div className="lb-rail">
        <div className="lb-rail-line" />
        <div className="lb-rail-prog" style={{ width: `${pct(idx)}%` }} />
        {releases.map((d, i) => (
          <React.Fragment key={d}>
            {marks[d] && <span className="lb-dot-mark" style={{ left: `${pct(i)}%` }} aria-hidden="true">{marks[d]}</span>}
            <button
              type="button"
              className={"lb-dot" + (i < idx ? " done" : "") + (i === idx ? " active" : "")}
              style={{ left: `${pct(i)}%` }}
              data-tip={tips[d] || d}
              aria-label={`Release ${tips[d] || d}`}
              aria-current={i === idx ? "true" : undefined}
              onClick={() => onChange(d)}
            />
          </React.Fragment>
        ))}
      </div>
      <div className="lb-tl-ends">
        <span>{releases[0]} · first</span>
        <span>{releases[last]} · latest</span>
      </div>
    </div>
  );
}
