// Score math shared by every surface. A category with no numeric column is skipped — the overall
// is the mean of the categories that HAVE a score, which is exactly the results sheet's Avg
// formula. A blank ("still running") and "n/a" (excluded on purpose) both fall out of the mean.

export const getGlobalAverageColumns = (checkedCategories, categories) => {
    return Object.entries(checkedCategories).flatMap(([category, checks]) =>
        checks.average ? categories[category] :
            checks.allSubcategories ? categories[category] : []
    );
};

export const getGlobalAverage = (row, checkedCategories, categories) => {
    const averages = Object.entries(checkedCategories)
        .filter(([, checks]) => checks.average || checks.allSubcategories)
        .map(([category]) => calculateAverage(row, categories[category]))
        .filter((v) => v !== '-' && !isNaN(v));
    const avg = averages.length ? averages.reduce((a, b) => a + b) / averages.length : NaN;
    return isNaN(avg) ? '-' : avg.toFixed(2);
};

export const calculateAverage = (row, columns, fixedSize) => {
    if (!columns) return '-';
    const validValues = columns.map(col => parseFloat(row[col])).filter(val => !isNaN(val));
    const average = validValues.length > 0 ? validValues.reduce((a, b) => a + b, 0) / validValues.length : NaN;
    return isNaN(average) ? '-' : fixedSize ? average.toFixed(fixedSize) : average;
};
