import React, { useState, useMemo, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "./App.css";
import { TIMELINE, releaseLabel, LAST_UPDATED } from "./lib/constants";
import useLeaderboardData from "./lib/useLeaderboardData";
import { overallOf, catAvg, overallCost } from "./lib/compute";
import { getModelInfo } from "./Table/modelLinks";
import { readHash } from "./lib/urlState";
import Navbar from "./components/Navbar";
import Tooltip from "./components/Tooltip";
import ReleaseTimeline from "./components/ReleaseTimeline";
import Leaderboard from "./components/Leaderboard";
import Insights from "./components/insights/Insights";
import V1Board from "./V1Board";

const LATEST = TIMELINE[TIMELINE.length - 1];
const byLabel = (label) => TIMELINE.find((e) => e.label === label);
const FIRST_V2 = TIMELINE.find((e) => e.gen === "v2");

// One release timeline across LiveBench v1 and 2.0 (see TIMELINE). The latest release is shown at
// #/ by default; #/release/<date> opens another one (a path, not a query param, so the boards' own
// URL state can't drop it). A 2.0 release renders the 2.0 board below; a v1 release renders the v1
// board (V1Board, from src/v1/), exactly as livebench.ai shows it.
export default function App() {
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const m = pathname.match(/^\/release\/([^/]+)/);
  const sel = (m && byLabel(decodeURIComponent(m[1]))) || LATEST;
  const pick = (label) => {
    const e = byLabel(label);
    if (e && e !== sel) navigate(e === LATEST ? "/" : `/release/${e.label}`);
  };
  const timeline = (
    <ReleaseTimeline releases={TIMELINE.map((e) => e.label)} value={sel.label} onChange={pick}
      marks={FIRST_V2 ? { [FIRST_V2.label]: "2.0" } : {}}
      tips={Object.fromEntries(TIMELINE.map((e) => [e.label, `${e.label} · LiveBench ${e.gen === "v2" ? "2.0" : "v1"}`]))} />
  );
  return sel.gen === "v1"
    ? <V1Board key={sel.label} date={sel.id} timeline={timeline} latest={LATEST.label} onLatest={() => pick(LATEST.label)} />
    : <V2Board key={sel.label} date={sel.id} isLatest={sel === LATEST} timeline={timeline} />;
}

function V2Board({ date, isLatest, timeline }) {
  // Finetunes are hidden by default in both the leaderboard and the insights; ?ft=1 opts in.
  // Shared here (not per-section) so the two never disagree about which models are in play.
  const [inclFinetunes, setInclFinetunes] = useState(() => readHash().get("ft") === "1");
  const toggleFinetunes = () => setInclFinetunes((v) => !v);
  const { rawData, categories, costMap, breakdown, hasCost, loading, error } = useLeaderboardData(date);

  // #/insights is a static link straight to the Insights section (same page, pre-scrolled).
  const { pathname } = useLocation();
  useEffect(() => {
    if (pathname !== "/insights" || loading) return;
    document.getElementById("lb-insights")?.scrollIntoView();
  }, [pathname, loading]);

  // Enrich each model row with metadata + computed scores once per load.
  // A model with NO score at all is dropped; one with some suites missing stays, with its
  // overall computed over the suites it has (nCats says how many) — same as the sheet's Avg.
  const models = useMemo(() => {
    const cats = categories || {};
    return rawData
      .map((row) => {
        const info = getModelInfo(row.model);
        if (!info) return null; // only models with metadata are shown
        const overall = overallOf(row, cats);
        if (overall == null) return null;
        const c = {};
        Object.keys(cats).forEach((k) => { c[k] = catAvg(row, cats, k); });
        const nCats = Object.values(c).filter((v) => v != null).length;
        const cost = hasCost && costMap[row.model] ? costMap[row.model] : null;
        return {
          model: row.model, row, info,
          name: info.displayName || row.model,
          org: info.organization || "Other",
          reasoner: !!info.reasoner, open: !!info.openweight, finetune: !!info.finetune,
          overall, cats: c, nCats, cost,
          costOverall: overallCost(cost, cats),
        };
      })
      .filter(Boolean);
  }, [rawData, categories, costMap, hasCost]);
  const hasFinetunes = models.some((m) => m.finetune);

  return (
    <div>
      <Tooltip />
      <Navbar variant="home" />

      <header className="lb-hero">
        <div className="lb-wrap">
          <p className="lb-eyebrow">LiveBench 2.0</p>
          <h1>A challenging, contamination-free long-horizon AI benchmark.</h1>
          <p className="sub">
            We give models real work (decks, research reports, bug fixes, apps that run for hours) and grade what they hand back.
          </p>
          {timeline}
          <p className="lb-tl-note" style={{ maxWidth: "62ch" }}>
            {isLatest ? (
              <>Last updated <b>{LAST_UPDATED}</b> — the latest release. <span style={{ color: "var(--live)" }}>● live</span></>
            ) : (
              <>Showing the <b>{releaseLabel(date)}</b> release.</>
            )}
          </p>
        </div>
      </header>

      <section className="lb-section" id="lb-leaderboard">
        <div className="lb-wrap">
          {loading && <div className="lb-state">Loading {releaseLabel(date)}…</div>}
          {error && <div className="lb-state err">Couldn't load this release. Please refresh the page.</div>}
          {!loading && !error && (
            <>
              <div className="lb-sec-head">
                <span className="lb-sec-no">01</span><h2>Leaderboard</h2>
              </div>
              <p className="lb-sec-sub">
                Overall + every suite, sortable. Click a row for its per-suite detail.
              </p>
              <Leaderboard key={date} models={models} categories={categories} breakdown={breakdown} hasCost={hasCost}
                inclFinetunes={inclFinetunes} onToggleFinetunes={toggleFinetunes} hasFinetunes={hasFinetunes} />
            </>
          )}
        </div>
      </section>

      {!loading && !error && models.length > 0 && (
        <Insights key={date} models={models} categories={categories} hasCost={hasCost}
          inclFinetunes={inclFinetunes} onToggleFinetunes={toggleFinetunes} hasFinetunes={hasFinetunes} />
      )}

      <footer className="lb-footer">
        <div className="lb-wrap">
          <span>LiveBench 2.0 · sponsored by Abacus.AI.</span>
          <span className="mono" style={{ color: "var(--faint)" }}>Overall = mean of the suites with a score · one run per suite</span>
        </div>
      </footer>
    </div>
  );
}
