import { RELEASES as V1_RELEASES } from "../v1/lib/constants";

// Release dates that have a published table_<date>.csv (+ categories_<date>.json + notes_<date>.json).
// A release is produced from the results sheet by scripts/sheet_to_release.py; add its date here
// (last entry = latest, shown by default).
export const RELEASES = ["2026-09-02"];

// Date shown for a release on the site. The key stays the data-file date (table_<key>.csv etc.);
// the label is when that release's data was last updated. A release not listed shows its key.
const RELEASE_LABELS = { "2026-09-02": "2026-10-14" };
export const releaseLabel = (d) => RELEASE_LABELS[d] || d;
export const LAST_UPDATED = "14 October 2026";

// The site's one release timeline: every LiveBench v1 release (the v1 board, copied into src/v1/ and
// public/v1/ by scripts/sync_v1.sh) followed by every LiveBench 2.0 release. The last entry is the
// latest and is shown by default; an older dot shows that release's v1 board, here on this site.
// `id` is the data-file date, `label` the date shown on the site and in the URL (#/?release=<label>).
export const TIMELINE = [
  ...V1_RELEASES.map((d) => ({ id: d, label: d, gen: "v1" })),
  ...RELEASES.map((d) => ({ id: d, label: releaseLabel(d), gen: "v2" })),
];
if (new Set(TIMELINE.map((e) => e.label)).size !== TIMELINE.length)
  throw new Error("Two releases share a date on the timeline (v1 RELEASES vs 2.0 RELEASE_LABELS)");

