// Column order of the suites on the board (after Overall, before cost). categories_<date>.json is
// reordered to this on load, so the scripts that write it need not care; a suite not listed goes last.
export const CAT_ORDER = ["Long-Horizon", "Reasoning", "Coding", "Browser", "Data Analysis", "Research", "Design", "App", "Data"];
export function orderCategories(categories) {
  const rank = (c) => { const i = CAT_ORDER.indexOf(c); return i < 0 ? CAT_ORDER.length : i; };
  const out = {};
  Object.keys(categories || {}).sort((a, b) => rank(a) - rank(b)).forEach((c) => { out[c] = categories[c]; });
  return out;
}

