import React, { useEffect, useState } from "react";
import { Helmet } from "react-helmet";
import "./App.css";
import Navbar from "./components/Navbar";
import { RELEASES, catFull, releaseLabel, LAST_UPDATED } from "./lib/constants";

const LATEST = RELEASES[RELEASES.length - 1];

// The seven suites on the board, in column order. Written by hand for a public audience: what the agent
// is asked to do, with representative kinds of task (no task ids), and one line on grading.
const SUITES = [
  {
    cat: "Long-Horizon",
    tasks: 18,
    summary: "Long-running work where early decisions have to hold up through later turns, months or test cases.",
    detail: {
      "Finance & Compliance Apps": "Take over a working app for payroll, council budgets, charity tax claims or audit evidence, and keep the figures and paper trail correct through rounds of changing rules.",
      "Operations & Commerce Apps": "Take over a working app for theatre ticketing, equipment hire, stock traceability or waste-site records, and keep it correct as the business changes around it.",
      "Long-Run Operations": "Run an existing codebase through simulated months of data releases, billing closes and change tickets, where an early shortcut surfaces much later.",
      "Systems Engineering": "Build a compiler from a written specification, repair a numerical physics simulator, and keep a service fleet healthy through a stream of incidents.",
      "Performance Optimisation": "Make existing compilers emit faster code and produce tighter workshop schedules, scored on measured results.",
    },
    grading: "Graded by scripts against hidden reference data, hidden test programs or simulated outcomes.",
  },
  {
    cat: "Reasoning",
    tasks: 202,
    unit: "questions",
    summary: "Short logic, spatial and theory-of-mind questions, each with a single correct answer. Not agentic: no tools, one answer per question.",
    grading: "Answers are checked against ground truth.",
  },
  {
    cat: "Coding",
    tasks: 29,
    summary: "Fix a real bug in a large production codebase, frozen at a fixed snapshot.",
    intro: "Each task is a bug that a real merged pull request fixed. The model gets a bug report and the repository, and must make the fix.",
    examples: "Stop a credit throttle double-counting usage, keep a memory index in a stable order, normalise image content for a provider's API, refuse shared storage buckets in a cloud connector.",
    grading: "Hidden tests check the fix; a fix that breaks existing behaviour scores 0.",
  },
  {
    cat: "Browser",
    tasks: 25,
    summary: "Complete multi-step jobs in working web applications, through a real browser that the model sees by screenshot.",
    intro: "The apps: an online shop, project boards, an appointment scheduler, an expense ledger, a support helpdesk and a wiki.",
    detail: {
      "Data Aggregation": "Roll-ups that need every record read, such as category or workload totals across many pages.",
      "Sequential Planning": "Order-dependent plans, such as placing several orders under shared constraints or rebooking a day's appointments.",
      "Analysis-Driven Action": "Work out a result from the data, then act on it, such as flagging and recategorising transactions by rule.",
      "Structural Integrity": "Edits that must keep structure intact, such as merging duplicate tickets or moving a page subtree and fixing its links.",
      "Constraint Adherence": "Exact input, and declining an action the app does not permit.",
    },
    grading: "The answer and the app's resulting data are checked against the expected outcome; the score is the share of tasks passed. A model that cannot take screenshots cannot do these tasks and scores 0.",
  },
  {
    cat: "Data Analysis",
    tasks: 150,
    unit: "questions",
    summary: "Short data-analysis questions on small tables, each with a single correct answer. Not agentic: no tools, one answer per question.",
    detail: {
      "Consecutive events": "Given a small table of dated values in mixed formats, find the entities with runs of consecutive growth.",
      "Table join": "Given two tables, one with obfuscated column names, map the columns of the first onto the second.",
      "Table reformat": "Convert a table between CSV, TSV, JSON, JSONL, Markdown and HTML.",
    },
    grading: "Answers are checked against ground truth.",
  },
  {
    cat: "Research",
    tasks: 22,
    summary: "Answer an open-ended brief by researching it and writing a report with sources.",
    intro: "Each brief comes from a named person in a specific situation (a shop owner, a compliance lead, a fund's investment committee), often with files attached, and asks for a decision or an answer they can act on.",
    examples: "Work out which flight disruptions in a claims log are owed compensation; check new packaging against organic labelling rules; trace which publication produced each number in an investment memo.",
    grading: "The report is graded against a task-specific rubric.",
  },
  {
    cat: "Design",
    tasks: 25,
    summary: "Produce or rework a finished document to a brief: Word documents, PDFs and slide decks.",
    detail: {
      "Documents (DOCX)": "Restyle an existing document, turn Markdown notes into a formatted one, lay out a one-pager, redesign a document.",
      "PDF": "An annual report, a brand sheet, a handbook, a menu, a poster, a gallery, and rebrands or restyles of existing PDFs.",
      "Presentations (PPT)": "Build a talk or a status (RAG) report, chart data on slides, apply a brand, redesign, cut down or localise a deck, work from a vague brief.",
    },
    grading: "The produced file is rendered and scored on visual and structural checks against the brief.",
  },
];

// How to read the numbers, plus the curated notes for the release (public/notes_<date>.json, written
// by hand for a public audience — the sync script never touches it).
export default function Methodology() {
  const [notes, setNotes] = useState(null);
  const [breakdown, setBreakdown] = useState({});
  useEffect(() => {
    const base = process.env.PUBLIC_URL || "";
    const v = process.env.REACT_APP_BUILD ? `?v=${process.env.REACT_APP_BUILD}` : "";
    const d = LATEST.replaceAll("-", "_");
    fetch(`${base}/notes_${d}.json${v}`)
      .then((r) => (r.ok ? r.json() : []))
      .then(setNotes)
      .catch(() => setNotes([]));
    fetch(`${base}/breakdown_${d}.json${v}`)
      .then((r) => (r.ok ? r.json() : {}))
      .then((b) => setBreakdown(b || {}))
      .catch(() => setBreakdown({}));
  }, []);
  const partsOf = (c) => (breakdown[c] && breakdown[c].parts) || null;

  return (
    <div>
      <Helmet><title>Methodology · LiveBench 2.0</title></Helmet>
      <Navbar variant="details" />
      <header className="lb-hero">
        <div className="lb-wrap">
          <p className="lb-eyebrow">Methodology</p>
          <h1>What the numbers mean.</h1>
          <p className="sub">
            The board has seven suites. Five are agentic: the model works through real end-to-end tasks with tools
            (plans, edits files, drives apps, runs code) and produces a result that is graded automatically.
            The other two, Data Analysis and Reasoning, are short sets of single-answer questions.{" "}
            <b>Each cell is the model's mean task score for that suite, 0–100, from a single run.</b>
          </p>
          <p className="lb-tl-note">Last updated <b>{LAST_UPDATED}</b>.</p>
        </div>
      </header>

      <section className="lb-section">
        <div className="lb-wrap">
          <div className="lb-sec-head lb-meth-head first"><span className="lb-sec-no">01</span><h2>The suites</h2></div>
          <div className="lb-card lb-meth-overview">
            <table className="lb-tbl">
              <thead><tr><th className="l">Suite</th><th>Tasks</th><th className="l">What the model is asked to do</th></tr></thead>
              <tbody>
                {SUITES.map((s) => (
                  <tr key={s.cat}>
                    <td className="l"><b>{catFull(s.cat)}</b></td>
                    <td className="num">{s.tasks}{s.unit ? ` ${s.unit}` : ""}</td>
                    <td className="l">{s.summary}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {SUITES.map((s) => (
            <article className="lb-card lb-meth-suite" key={s.cat}>
              <h3 className="ms-title">{catFull(s.cat)} <span className="ms-count">{s.tasks} {s.unit || "tasks"}</span></h3>
              <p className="ms-summary">{s.summary}</p>
              {s.intro && <p className="ms-text">{s.intro}</p>}
              {partsOf(s.cat) && (
                <div className="ms-parts" role="table" aria-label={`${catFull(s.cat)} subcategories`}>
                  {partsOf(s.cat).map((p) => (
                    <div className="ms-row" role="row" key={p.name}>
                      <div className="ms-name" role="cell">{p.name}</div>
                      <div className="ms-n" role="cell">{p.tasks || ""}</div>
                      <div className="ms-desc" role="cell">{(s.detail && s.detail[p.name]) || p.gloss}</div>
                    </div>
                  ))}
                </div>
              )}
              {s.examples && <p className="ms-text"><span className="ms-label">Examples</span>{s.examples}</p>}
              <p className="ms-text ms-grading"><span className="ms-label">Grading</span>{s.grading}</p>
            </article>
          ))}

          <div className="lb-sec-head lb-meth-head"><span className="lb-sec-no">02</span><h2>How a cell is computed</h2></div>
          <div className="lb-card">
            <ul className="lb-meth-terms">
              <li><b>Suite score</b><span>Each task is scored 0–100 and the cell is the mean over the suite's tasks.</span></li>
              <li><b>Single run</b><span>Each suite is one run per model.</span></li>
              <li><b>Effort</b><span>Models run at their highest supported effort setting. Where a different setting was used, the model's expanded row shows it.</span></li>
              <li><b>Subcategories</b><span>A model's expanded row shows its score in each subcategory listed above. The suite score is computed over all of its tasks; it is not the mean of the subcategory scores. For Design and Research the subcategory scores are scaled so that they reconcile to the suite score; for Browser Use, Coding and Agentic they are the raw scores over the tasks in each subcategory, so a subcategory in one suite is not directly comparable with one in another. Data Analysis and Reasoning are the exception: each score is the equal-weight mean of its subcategories. A dash means no task in that subcategory produced a gradeable result for that model.</span></li>
            </ul>
          </div>

          <div className="lb-sec-head lb-meth-head"><span className="lb-sec-no">03</span><h2>Reading a row</h2></div>
          <div className="lb-card">
            <ul className="lb-meth-terms">
              <li><b>Overall</b><span>The mean of the suites that have a score for that model, each suite counting equally.</span></li>
              <li><b>A blank cell (—)</b><span>The suite is still running or being re-run for that model. It contributes nothing to Overall.</span></li>
              <li><b>n/a</b><span>The model was excluded from that suite on purpose. A model that lacks an input the suite needs — a text-only model on the Browser Use suite, which works by screenshot — is not excluded: it scores 0 there, because it cannot do the work.</span></li>
            </ul>
          </div>

          <div className="lb-sec-head lb-meth-head"><span className="lb-sec-no">04</span><h2>Cost</h2></div>
          <div className="lb-card">
            <ul className="lb-meth-terms">
              <li><b>Cost per task</b><span>Counts every call the model under test made in the run, priced at the provider's list rates, with cached input at the cached rate. It leaves out the fixed starting state some tasks come with and the harness's own helper calls.</span></li>
              <li><b>Across suites</b><span>Cost per task is total cost ÷ total tasks over the suites in scope, so every task (or Data Analysis and Reasoning question) counts once; it is not the mean of the per-suite figures. Agentic tasks run tens of calls over a long context and cost far more than a single-answer question, so including the many Data Analysis and Reasoning questions lowers a model's overall cost per task.</span></li>
              <li><b>Cost per successful task</b><span>(Cost per task ÷ score) × 100 over whichever suites are selected, so failures and partial credit raise it.</span></li>
            </ul>
          </div>

          <div className="lb-sec-head lb-meth-head"><span className="lb-sec-no">05</span><h2>Release notes · {releaseLabel(LATEST)}</h2></div>
          <div className="lb-card">
            {notes == null && <div className="lb-state">Loading…</div>}
            {notes && notes.length === 0 && <div className="lb-state">No notes for this release.</div>}
            {notes && notes.length > 0 && (
              <ol className="lb-meth-notes">
                {notes.map((n, i) => <li key={i}>{n}</li>)}
              </ol>
            )}
          </div>

          <div className="lb-sec-head lb-meth-head"><span className="lb-sec-no">06</span><h2>Data</h2></div>
          <div className="lb-card">
            <p className="ms-text">
              Each release is a set of static files in <span className="mono">public/</span>:{" "}
              <span className="mono">table_&lt;date&gt;.csv</span> (one row per model, one column per suite, raw 0–100 or <span className="mono">n/a</span> or blank),{" "}
              <span className="mono">categories_&lt;date&gt;.json</span> (suite → its columns),{" "}
              <span className="mono">cost_&lt;date&gt;.csv</span> (cost and task counts per suite),{" "}
              <span className="mono">breakdown_&lt;date&gt;.json</span> (subcategory scores) and{" "}
              <span className="mono">notes_&lt;date&gt;.json</span> (the release notes above).
              Overall and everything derived from it are computed in the browser, never stored.
            </p>
          </div>
        </div>
      </section>

      <footer className="lb-footer">
        <div className="lb-wrap">
          <span>LiveBench 2.0 · sponsored by Abacus.AI.</span>
          <a href="./#/">← Back to the leaderboard</a>
        </div>
      </footer>
    </div>
  );
}
