import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';
import 'bulma/css/bulma.css';
import '@fortawesome/fontawesome-free/css/all.css';
import './index.css';
import App from './App';
import Methodology from './Methodology';
import reportWebVitals from './reportWebVitals';

// v1-only routes of the old livebench.ai (the v1 board now lives at /v1/): send old deep links there.
function V1Redirect({ route }) {
  React.useEffect(() => { window.location.replace(`/v1/#/${route}`); }, [route]);
  return null;
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <Router>
      <Routes>
        <Route path="/" element={<App />} />
        <Route path="/insights" element={<App />} />
        <Route path="/release/:date" element={<App />} />
        <Route path="/methodology" element={<Methodology />} />
        <Route path="/details" element={<Methodology />} />
        <Route path="/finetunes" element={<V1Redirect route="finetunes" />} />
      </Routes>
    </Router>
  </React.StrictMode>
);

// If you want to start measuring performance in your app, pass a function
// to log results (for example: reportWebVitals(console.log))
// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals
reportWebVitals();
