import React, { useState, useMemo } from "react";
import useLeaderboardData from "./v1/lib/useLeaderboardData";
import { overallOf, catAvg, overallCost, ftModeFromParam, resolveFinetuneBase } from "./v1/lib/compute";
import { getModelInfo } from "./v1/Table/modelLinks";
import { readHash } from "./v1/lib/urlState";
import Navbar from "./components/Navbar";
import Tooltip from "./components/Tooltip";
import Leaderboard from "./v1/components/Leaderboard";
import Insights from "./v1/components/insights/Insights";

// A LiveBench v1 release, as livebench.ai shows it: v1's own leaderboard + insights, run on v1's
// data and model metadata (src/v1/ + public/v1/, copied from LiveBench/new-livebench by
// scripts/sync_v1.sh). This file is the v1 site's App body (minus its Details/finetunes routes)
// under this site's timeline; keep it in step with new-livebench's src/App.js.
export default function V1Board({ date, timeline, latest, onLatest }) {
  // ?ft=1 lists finetunes among everything else; ?ft=only shows them next to their base models.
  const [ftMode, setFtMode] = useState(() => ftModeFromParam(readHash().get("ft")));
  const { rawData, categories, costMap, hasCost, loading, error } = useLeaderboardData(date);

  const models = useMemo(() => {
    const cats = categories || {};
    const list = rawData
      .map((row) => {
        const info = getModelInfo(row.model);
        if (!info) return null; // mirror the v1 site: only models with metadata are shown
        const overall = overallOf(row, cats);
        if (overall == null) return null;
        const c = {};
        Object.keys(cats).forEach((k) => { c[k] = catAvg(row, cats, k); });
        const cost = hasCost && costMap[row.model] ? costMap[row.model] : null;
        return {
          model: row.model, row, info,
          name: info.displayName || row.model,
          org: info.organization || "Other",
          reasoner: !!info.reasoner, open: !!info.openweight, finetune: !!info.finetune,
          overall, cats: c, cost,
          costOverall: overallCost(cost, cats),
        };
      })
      .filter(Boolean);
    list.forEach((m) => { m.baseKey = m.finetune ? resolveFinetuneBase(m, list) : null; });
    return list;
  }, [rawData, categories, costMap, hasCost]);
  const taskCount = Object.values(categories).reduce((s, a) => s + (a ? a.length : 0), 0);
  const catCount = Object.keys(categories).length;

  return (
    <div>
      <Tooltip />
      <Navbar variant="home" />

      <header className="lb-hero">
        <div className="lb-wrap">
          <p className="lb-eyebrow">LiveBench v1 · contamination-free LLM benchmark</p>
          <h1>A challenging, contamination-free LLM benchmark.</h1>
          <p className="sub">
            {taskCount || 23} objective tasks across {catCount || 7} categories, refreshed every six months.{" "}
            <b>Pick a release, compare scores down to the subtask, and see what each model costs to run.</b>
          </p>
          {timeline}
          <p className="lb-tl-note" style={{ maxWidth: "62ch" }}>
            Showing <b>LiveBench-{date}</b>, a LiveBench v1 release.{!hasCost && " Cost data is published for v1's latest release only."}{" "}
            The latest release is LiveBench 2.0 ({latest}):{" "}
            <button type="button" className="lb-linkbtn" onClick={onLatest}>see it →</button>
          </p>
        </div>
      </header>

      <section className="lb-section" id="lb-leaderboard">
        <div className="lb-wrap">
          {loading && <div className="lb-state">Loading {date}…</div>}
          {error && <div className="lb-state err">Couldn't load this release. Please refresh the page.</div>}
          {!loading && !error && (
            <>
              <div className="lb-sec-head">
                <span className="lb-sec-no">01</span><h2>Leaderboard</h2>
              </div>
              <p className="lb-sec-sub">
                Overall + every category, sortable. Click a row for its subtask scores.
                {hasCost ? " Cost sits right beside the scores." : ""}
              </p>
              <Leaderboard key={date} models={models} categories={categories} hasCost={hasCost}
                ftMode={ftMode} onFtMode={setFtMode} />
            </>
          )}
        </div>
      </section>

      {!loading && !error && models.length > 0 && (
        <Insights key={date} models={models} categories={categories} hasCost={hasCost}
          ftMode={ftMode} onFtMode={setFtMode} />
      )}

      <footer className="lb-footer">
        <div className="lb-wrap">
          <span>LiveBench v1 · sponsored by Abacus.AI · a contamination-free LLM benchmark.</span>
          <span className="mono" style={{ color: "var(--faint)" }}>Overall = mean of category averages · cost = cost per successful task</span>
        </div>
      </footer>
    </div>
  );
}
