import React, { useState, useEffect, useMemo } from "react";
import { catFull, subtaskLabel, CAT_BLURB } from "../lib/constants";
import { collapseVariants, costForCategories, weightedMean, isEqualWeights, effectiveWeights, encodeWeights } from "../lib/compute";
import { getHuggingFaceUrl } from "../Table/modelLinks";
import { readHash, writeHash } from "../lib/urlState";
import FinetuneChip from "./FinetuneChip";
import ColumnChooser from "./ColumnChooser";
import ModelCompare from "./ModelCompare";

// Render $X with the "$" in a .cur span (size-only nudge — see index.css).
const Money = ({ v, dp }) => (v == null ? "—" : <><span className="cur">$</span>{v.toFixed(dp)}</>);

// Subcategory columns (shown when one suite is focused) are keyed "part:<Category>:<name>" so they
// can't collide with real subtask columns. They are display-only values from the breakdown file.
const PART = "part:";
const partKey = (c, name) => `${PART}${c}:${name}`;
const partOf = (k) => {
  if (!k.startsWith(PART)) return null;
  const i = k.indexOf(":", PART.length);
  return { cat: k.slice(PART.length, i), name: k.slice(i + 1) };
};
const partEntry = (m, k, breakdown) => {
  const p = partOf(k);
  return p && breakdown[p.cat] && breakdown[p.cat].models ? breakdown[p.cat].models[m.model] : undefined;
};
// (partEntry is also what numVal reads; there is no per-cell provenance on the site)

// Numeric value of a score column key: "overall", a category name (average), a subcategory
// ("part:…"), or a subtask column (raw score).
const numVal = (m, k, breakdown = {}) => {
  if (k === "overall") return m.overall;
  if (k.startsWith(PART)) {
    const e = partEntry(m, k, breakdown);
    const v = e && e.scores ? e.scores[partOf(k).name] : null;
    return v == null || isNaN(Number(v)) ? null : Number(v);
  }
  if (m.cats[k] !== undefined) return m.cats[k];      // category average
  const v = m.row[k];                                  // subtask raw score
  if (v == null || v === "") return null;
  const n = Number(v);
  return isNaN(n) ? null : n;                          // "n/a" (excluded) reads as no value, never 0
};

// True when the raw cell(s) behind a column carry the explicit "n/a" exclusion marker.
const isExcluded = (m, k, categories) => {
  const cols = k in categories ? categories[k] : [k];
  return cols.some((t) => typeof m.row[t] === "string" && m.row[t].toLowerCase().startsWith("n/a"));
};
// Cell text: score, "n/a" (excluded on purpose) or "—" (blank = still running).
const cellText = (m, k, v, categories) => (v != null ? v.toFixed(1) : k !== "overall" && isExcluded(m, k, categories) ? "n/a" : "—");

// Relative shading: the top 5 in each score column get an accent tint, darkest (rank 1) → lightest (rank 5).
const SHADES = ["rgba(47,84,235,0.24)", "rgba(47,84,235,0.17)", "rgba(47,84,235,0.115)", "rgba(47,84,235,0.07)", "rgba(47,84,235,0.035)"];
function computeShades(rows, cols, valFn) {
  const map = {};
  for (const c of cols) {
    const vals = rows.map((m) => ({ model: m.model, v: valFn(m, c) }))
      .filter((x) => x.v != null).sort((a, b) => b.v - a.v);
    const cm = {};
    vals.slice(0, 5).forEach((x, i) => { cm[x.model] = SHADES[i]; });
    map[c] = cm;
  }
  return map;
}

// inclFinetunes is owned by App (shared with Insights); everything else is local view state.
export default function Leaderboard({ models, categories, breakdown = {}, hasCost, inclFinetunes, onToggleFinetunes, hasFinetunes = true, weights = {} }) {
  const cats = Object.keys(categories);
  // Category weights (owned by App; models[].overall already uses them). eff = what actually applies.
  const weighted = !isEqualWeights(weights, cats);
  const eff = effectiveWeights(weights, cats);

  // initialize view state from the URL so links are shareable
  const init = readHash();
  const initCats = (init.get("cats") || "").split(",").map((s) => s.trim()).filter((c) => c && categories[c]);
  const [selectedCats, setSelectedCats] = useState(initCats);
  const [sortKey, setSortKey] = useState(init.get("sort") || (initCats.length === 1 ? initCats[0] : "overall"));
  const [sortDir, setSortDir] = useState(init.get("dir") === "asc" ? 1 : -1);
  const [expanded, setExpanded] = useState(() => new Set());
  const [onlyOpen, setOnlyOpen] = useState(init.get("open") === "1");
  const [q, setQ] = useState("");
  const [showOrg, setShowOrg] = useState(init.get("showorg") === "1");
  const [orgFilter, setOrgFilter] = useState(init.get("org") || "");
  // hidden column groups: "overall", a category key, or "cpst" (cost per successful task)
  const [hiddenCols, setHiddenCols] = useState(() => new Set(
    (init.get("hide") || "").split(",").filter((k) => k === "overall" || k === "cpst" || categories[k])
  ));
  // compare filter: ids of the (collapsed) rows to show; empty = show all
  const [compareSet, setCompareSet] = useState(() => {
    const ids = new Set(collapseVariants(models).map((m) => m.model));
    return new Set((init.get("compare") || "").split(",").map((s) => s.trim()).filter((id) => ids.has(id)));
  });

  const orgs = [...new Set(models.map((m) => m.org).filter(Boolean))].sort();

  const nSel = selectedCats.length;
  const single = nSel === 1 ? selectedCats[0] : null;   // the one category, when exactly one is selected
  const scopeCats = nSel === 0 ? cats : selectedCats;   // categories the cost/score scope covers

  // 1 category → its score + its subcategory columns (when a breakdown exists) + its subtask columns
  // (only when it has more than one, since a lone subtask just repeats the suite score);
  // 2+ → Overall(selected) + the selected categories; 0 → Overall + all.
  const partCols = (c) => (breakdown[c] && breakdown[c].parts ? breakdown[c].parts.map((p) => partKey(c, p.name)) : []);
  const scoreCols = single
    ? [single, ...partCols(single), ...(categories[single].length > 1 ? categories[single] : [])]
    : ["overall", ...(nSel >= 2 ? selectedCats : cats)];

  // ---- column chooser: hide/show column groups ("overall", each category, "cpst") ----
  const groupOf = (k) => (k === "overall" || k in categories ? k : single); // subtask columns belong to the focused category
  const visibleCols = scoreCols.filter((k) => !hiddenCols.has(groupOf(k)));
  const showCost = hasCost && !hiddenCols.has("cpst");
  const colGroups = [
    { key: "overall", label: "Overall" },
    ...cats.map((c) => ({ key: c, label: catFull(c) })),
    ...(hasCost ? [{ key: "cpst", label: "Cost per successful task" }] : []),
  ];

  // score of the current scope = weighted mean of its category averages (equal weights by default).
  const scopeScore = (m) => weightedMean(m.cats || {}, scopeCats, eff);
  // Overall column value: true overall when nothing is selected, else mean of the selected categories.
  const val = (m, k) => (k === "overall" ? (nSel === 0 ? m.overall : scopeScore(m)) : numVal(m, k, breakdown));

  // Cost per successful task = (Σ cost ÷ Σ questions over the scope's subtasks) ÷ scope score × 100.
  const costScope = (m) => (m.cost ? costForCategories(m.cost, categories, scopeCats) : null);
  const costPerSuccess = (m) => {
    const c = costScope(m), s = nSel === 0 ? m.overall : scopeScore(m);
    return c != null && s ? (c / s) * 100 : null;
  };

  // reflect focus + sort in the URL (shareable, no history spam)
  useEffect(() => {
    const p = new URLSearchParams();
    if (selectedCats.length) p.set("cats", selectedCats.join(","));
    const isDefault = sortKey === (single || "overall") && sortDir === -1;
    if (!isDefault) { p.set("sort", sortKey); p.set("dir", sortDir < 0 ? "desc" : "asc"); }
    if (onlyOpen) p.set("open", "1");
    if (inclFinetunes) p.set("ft", "1");
    if (showOrg) p.set("showorg", "1");
    if (orgFilter) p.set("org", orgFilter);
    if (hiddenCols.size) p.set("hide", [...hiddenCols].join(","));
    if (compareSet.size) p.set("compare", [...compareSet].join(","));
    const wq = encodeWeights(weights, cats);
    if (wq) p.set("w", wq);
    writeHash(p);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedCats, single, sortKey, sortDir, onlyOpen, inclFinetunes, showOrg, orgFilter, hiddenCols, compareSet, weights]);

  const sortVal = (m, k) => {
    if (k === "cpst") return costPerSuccess(m);
    if (k === "model") return m.name.toLowerCase();
    if (k === "org") return (m.org || "").toLowerCase();
    return val(m, k);
  };

  const rows = useMemo(() => {
    let r = models.filter((m) => {
      if (onlyOpen && !m.open) return false;
      if (!inclFinetunes && m.finetune) return false;
      if (orgFilter && m.org !== orgFilter) return false;
      if (q && !m.name.toLowerCase().includes(q) && !m.model.toLowerCase().includes(q)) return false;
      return true;
    });
    r = collapseVariants(r);
    if (compareSet.size) r = r.filter((m) => compareSet.has(m.model));
    return r.slice().sort((a, b) => {
      const va = sortVal(a, sortKey), vb = sortVal(b, sortKey);
      if (va == null) return 1;
      if (vb == null) return -1;
      if (typeof va === "string") return va < vb ? -sortDir : va > vb ? sortDir : 0;
      return (va - vb) * sortDir;
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [models, onlyOpen, inclFinetunes, orgFilter, q, sortKey, sortDir, selectedCats, compareSet, weights]);

  // compare panel options: every (collapsed) model in the table, default order (overall desc)
  const compareOptions = useMemo(
    () => collapseVariants(models.filter((m) => inclFinetunes || !m.finetune))
      .sort((a, b) => (b.overall ?? -1) - (a.overall ?? -1)),
    [models, inclFinetunes]
  );

  const shades = computeShades(rows, visibleCols, val);

  const toggleCol = (g) => {
    const n = new Set(hiddenCols);
    n.has(g) ? n.delete(g) : n.add(g);
    setHiddenCols(n);
    // if the current sort column was just hidden, fall back to the first visible score column
    const sortGroup = sortKey === "cpst" ? "cpst" : sortKey === "model" || sortKey === "org" ? null : groupOf(sortKey);
    if (sortGroup && n.has(sortGroup)) {
      const k = scoreCols.find((c) => !n.has(groupOf(c)));
      setSortKey(k || "model");
      setSortDir(k ? -1 : 1);
    }
  };
  const resetCols = () => setHiddenCols(new Set());

  const clearCats = () => { setSelectedCats([]); setSortKey("overall"); setSortDir(-1); };
  const toggleCat = (c) => {
    const next = selectedCats.includes(c)
      ? selectedCats.filter((x) => x !== c)
      : cats.filter((x) => x === c || selectedCats.includes(x)); // keep canonical category order
    setSelectedCats(next);
    // explicitly focusing a category un-hides its columns
    if (next.includes(c) && hiddenCols.has(c)) setHiddenCols((s) => { const n = new Set(s); n.delete(c); return n; });
    setSortKey(next.length === 1 ? next[0] : "overall");
    setSortDir(-1);
  };
  const clickSort = (k) => {
    if (sortKey === k) setSortDir((d) => -d);
    // cost columns + model name sort ascending first; score columns sort descending first.
    else { setSortKey(k); setSortDir((k === "model" || k === "cpst" || k === "org") ? 1 : -1); }
  };
  const arrow = (k) => (k === sortKey ? <span className="arr">{sortDir < 0 ? "▼" : "▲"}</span> : null);
  const toggleRow = (model) =>
    setExpanded((s) => { const n = new Set(s); n.has(model) ? n.delete(model) : n.add(model); return n; });

  const partMeta = (k) => { const p = partOf(k); return p && breakdown[p.cat].parts.find((x) => x.name === p.name); };
  const headLabel = (k) => (k === "overall" ? (weighted ? "Overall (w)" : "Overall") : k in categories ? catFull(k) : partOf(k) ? `${partOf(k).name}${partMeta(k).tasks ? ` (${partMeta(k).tasks})` : ""}` : subtaskLabel(k));
  const headTitle = (k) => (k === "overall"
    ? `Overall — ${weighted ? "weighted mean (your weights)" : "mean"} of ${nSel >= 2 ? "the selected category averages" : "category averages"}`
    : k in categories ? `${catFull(k)} — ${CAT_BLURB[k] || ""}`
    : partOf(k) ? `${partMeta(k).name} — ${partMeta(k).gloss}`
    : subtaskLabel(k));
  const colCount = 2 + visibleCols.length + (showCost ? 1 : 0) + (showOrg ? 1 : 0);

  return (
    <>
      <div className="lb-controls">
        <div className="lb-search">
          <input type="text" value={q} placeholder="Search models…" aria-label="Search models"
            onChange={(e) => setQ(e.target.value.toLowerCase())} />
        </div>
        <button className="lb-chip" aria-pressed={onlyOpen} onClick={() => setOnlyOpen((v) => !v)}>Open weights</button>
        {hasFinetunes && <FinetuneChip on={inclFinetunes} onToggle={onToggleFinetunes} />}
        <button className="lb-chip" aria-pressed={showOrg} data-tip="Show the organization column"
          onClick={() => setShowOrg((v) => !v)}>Show org</button>
        <select className="lb-org-select" value={orgFilter} onChange={(e) => setOrgFilter(e.target.value)} aria-label="Filter by organization">
          <option value="">All organizations</option>
          {orgs.map((o) => <option key={o} value={o}>{o}</option>)}
        </select>
        <ModelCompare options={compareOptions} active={compareSet} onApply={setCompareSet} />
        <ColumnChooser groups={colGroups} hidden={hiddenCols} onToggle={toggleCol} onReset={resetCols} />
      </div>

      <div className="lb-cats">
        <span className="lb-cats-label">Category</span>
        <button className="lb-chip" aria-pressed={nSel === 0} onClick={clearCats}>All</button>
        {cats.map((c) => (
          <button key={c} className="lb-chip" data-tip={catFull(c)} aria-pressed={selectedCats.includes(c)} onClick={() => toggleCat(c)}>{catFull(c)}</button>
        ))}
      </div>

      <div className={"lb-tbl-scroll" + (hiddenCols.size ? " fit" : "")}>
        <table className="lb-tbl">
          <thead>
            <tr>
              <th className="l" style={{ width: 30 }} aria-hidden="true" />
              <th className="l mdl-col" onClick={() => clickSort("model")}><span className="th-h"><span className="th-t">Model</span>{arrow("model")}</span></th>
              {showOrg && <th className="l org-col" data-tip="Organization" onClick={() => clickSort("org")}><span className="th-h"><span className="th-t">Org</span>{arrow("org")}</span></th>}
              {visibleCols.map((k) => (
                <th key={k} className={k !== scoreCols[0] ? "sub" : undefined} data-tip={headTitle(k)} onClick={() => clickSort(k)}>
                  <span className="th-h"><span className="th-t">{headLabel(k)}</span>{arrow(k)}</span>
                </th>
              ))}
              {showCost && <th className="grp wrap2" data-tip="Cost per successful task = (cost per task ÷ score) × 100 for the selected scope — penalises failures / partial credit" onClick={() => clickSort("cpst")}><span className="th-h"><span className="th-t">Cost per<br />successful&nbsp;task</span>{arrow("cpst")}</span></th>}
            </tr>
          </thead>
          <tbody>
            {rows.map((m) => {
              const open = expanded.has(m.model);
              const cpst = costPerSuccess(m);     // scope-aware cost per successful task
              return (
                <React.Fragment key={m.model}>
                  <tr className={"row" + (open ? " open" : "")} onClick={() => toggleRow(m.model)}>
                    <td className="l lb-rank"><span className="lb-exp">▸</span></td>
                    <td className="l mdl-col">
                      <div className="lb-mdl">
                        <span className="nm" data-tip={m.info.effort ? `${m.name} · reasoning effort: ${m.info.effort}` : m.name}>{m.name}</span>
                        {m.open && <span className="opn">open</span>}
                      </div>
                    </td>
                    {showOrg && <td className="l org-col">{m.org}</td>}
                    {visibleCols.map((k) => {
                      const v = val(m, k);
                      return (
                        <td key={k} className={k === scoreCols[0] ? "lb-ovr" : "lb-cat"} style={{ background: shades[k] && shades[k][m.model] }}>
                          {partOf(k) ? (v == null ? "—" : v.toFixed(0)) : cellText(m, k, v, categories)}
                        </td>
                      );
                    })}
                    {showCost && <td className={"lb-cost-col" + (cpst != null ? "" : " na")}><Money v={cpst} dp={3} /></td>}
                  </tr>
                  {open && (
                    <tr className="lb-detail">
                      <td colSpan={colCount}>
                        <div className="lb-detail-in">
                          <div className="lb-det-meta">
                            {m.info.finetune ? (
                              <>
                                <span><span className="k">Finetune from:</span>{m.info.finetune.organization}</span>
                                <span><span className="k">Base model:</span>{m.info.finetune.baseModel} (from {m.info.finetune.baseOrganization})</span>
                              </>
                            ) : (
                              <span><span className="k">From:</span>{m.info.organization ?? "—"}</span>
                            )}
                            {m.info.version && <span><span className="k">Version:</span>{m.info.version}</span>}
                            {m.info.effort && <span><span className="k">Effort:</span>{m.info.effort}</span>}
                            {getHuggingFaceUrl(m.info) && <a href={getHuggingFaceUrl(m.info)} target="_blank" rel="noopener noreferrer">Hugging Face ↗</a>}
                          </div>
                          <div className="lb-det-grid">
                            {(selectedCats.length ? selectedCats : cats).map((c) => {
                              // Optional subcategory breakdown for this suite + model (display-only —
                              // the suite score above it is the published number, never recomputed here).
                              const bd = breakdown[c] && breakdown[c].models && breakdown[c].models[m.model];
                              return (
                                <div className="lb-det-cat" key={c}>
                                  <div className="h">{catFull(c)}</div>
                                  {categories[c].map((t) => {
                                    const v = m.row[t];
                                    const val = v == null || v === "" ? "—" : isNaN(Number(v)) ? String(v) : Number(v).toFixed(1);
                                    return (
                                      <div className="lb-subt" key={t}>
                                        <span className="n">{subtaskLabel(t)}</span>
                                        <span className="v">{val}</span>
                                      </div>
                                    );
                                  })}
                                  {bd && (
                                    <div className="lb-parts">
                                      {breakdown[c].parts.map((p) => (
                                        <div className="lb-subt lb-part" key={p.name} data-tip={p.gloss}>
                                          <span className="n">{p.name}{p.tasks ? <span className="cnt"> ({p.tasks})</span> : null}</span>
                                          <span className="v">{bd.scores[p.name] == null ? "—" : Number(bd.scores[p.name]).toFixed(0)}</span>
                                        </div>
                                      ))}
                                    </div>
                                  )}
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
      <p className="lb-foot-note">
        {nSel === 1
          ? `// ${catFull(single)}${partCols(single).length ? " — suite score + subcategory scores (the suite score is computed over all tasks, not the mean of the subcategories)" : " — its score"} · click "All" to reset`
          : nSel >= 2
          ? `// comparing ${nSel} categories — Overall = mean of the selected · click "All" to reset`
          : "// Overall = mean of the suites with a score · shading = top 5 per column"}
        {hasCost ? " · Cost per successful task = (Σ cost ÷ Σ tasks ÷ score) × 100 over the selected scope" : ""}
      </p>
    </>
  );
}
